#include "helper.hpp"
bool strong(vector<int>a){int n=a.size();for(int k=0;k<n;k++)for(int i=0;i<n;i++)if(a[i]>>k&1)a[i]|=a[k];for(int i=0;i<n;i++)if((a[i]|(1<<i))!=((1<<n)-1))return false;return true;}
int main(){int code=41;vector<int>a(5);int k=0;for(int i=0;i<5;i++)for(int j=i+1;j<5;j++,k++)if(code>>k&1)a[i]|=1<<j;else a[j]|=1<<i;if(hp(a)!=13||!strong(a))return 1;for(int v=0;v<5;v++){vector<int>old;for(int u=0;u<5;u++)if(u!=v)old.push_back(u);vector<int>b(7);for(int i=0;i<4;i++)for(int j=0;j<4;j++)if(a[old[i]]>>old[j]&1)b[i]|=1<<j;b[4]|=1<<5;b[5]|=1<<6;b[6]|=1<<4;int all[3]={},s[3]={};for(int m=0;m<(1<<12);m++){auto c=b;for(int t=0;t<3;t++)for(int u=0;u<4;u++)if(m>>(t*4+u)&1)c[4+t]|=1<<u;else c[u]|=1<<(4+t);int h=hp(c);for(int j=0;j<3;j++)if(h==39+2*j){all[j]++;s[j]+=strong(c);}}cout<<"root="<<v<<" counts=";for(int j=0;j<3;j++)cout<<" "<<39+2*j<<":"<<all[j]<<"/"<<s[j];cout<<" (all/strong)\n";}}
